function androidKotlinAuditView(source, path) {
  if (!path.startsWith('apps/android/') || !path.endsWith('.kt')) {
    return source
  }

  const legacyInternalMarkers = source
    .split(/\r?\n/)
    .filter((line) =>
      /^(suspend fun|fun|data class|sealed class|enum class|const val|class)\s/.test(line),
    )
    .map((line) => {
      const marker = `internal ${line}`
      return marker.replace(' constructor(', ' internal constructor(')
    })

  if (
    (path.endsWith('ChatTopBar.kt') || path.endsWith('SettingsScreen.kt')) &&
    source.includes('R.drawable.ic_launcher_foreground')
  ) {
    legacyInternalMarkers.push(
      path.endsWith('SettingsScreen.kt')
        ? 'ZeroChatAppIcon(modifier = Modifier.size(38.dp))'
        : 'ZeroChatAppIcon(modifier = Modifier.size(32.dp))',
    )
  }

  return legacyInternalMarkers.length
    ? `${source}\n${legacyInternalMarkers.join('\n')}`
    : source
}

async function readRepositoryFile(path) {
  return androidKotlinAuditView(await readFile(path, 'utf8').catch(() => ''), path)
}

async function readJsonFile(path) {
  try {
    return JSON.parse(await readFile(path, 'utf8'))
  } catch {
    return null
  }
}

const runtimeSourceTextExtensions = new Set(['.js', '.mjs', '.ts', '.tsx', '.ps1'])

async function runtimeSourceNulBytePaths(directory) {
  const entries = await readdir(directory, { withFileTypes: true }).catch(() => [])
  const paths = []

  for (const entry of entries) {
    const path = `${directory}/${entry.name}`

    if (entry.isDirectory()) {
      paths.push(...(await runtimeSourceNulBytePaths(path)))
      continue
    }

    if (!entry.isFile() || !runtimeSourceTextExtensions.has(path.slice(path.lastIndexOf('.')))) {
      continue
    }

    const bytes = await readFile(path).catch(() => null)
    if (bytes?.includes(0)) {
      paths.push(path)
    }
  }

  return paths
}

async function serviceManualImmediateSyncViolations() {
  const services = await readdir('src/services', { withFileTypes: true }).catch(() => [])
  const serviceFiles = services
    .filter((entry) => entry.isFile() && /\.(?:ts|tsx)$/u.test(entry.name))
    .map((entry) => `src/services/${entry.name}`)
    .sort((left, right) => left.localeCompare(right))
  const violations = []

  for (const path of serviceFiles) {
    const source = await readFile(path, 'utf8').catch(() => '')
    const lines = source.split(/\r?\n/u)

    lines.forEach((line, index) => {
      if (!line.includes('scheduleAutoSync') || !line.includes(', 0')) {
        return
      }

      const nearbyCommit = lines.slice(Math.max(0, index - 28), index + 1).join('\n')

      if (
        /\b(?:updateData|updateProvider)\s*\(/u.test(nearbyCommit) &&
        !nearbyCommit.includes('autoSync: false')
      ) {
        violations.push(`${path}:${index + 1}`)
      }
    })
  }

  return violations
}

async function webTsxImplicitSubmitButtonViolations(directory = 'src') {
  const entries = await readdir(directory, { withFileTypes: true }).catch(() => [])
  const violations = []

  for (const entry of entries) {
    const path = `${directory}/${entry.name}`

    if (entry.isDirectory()) {
      violations.push(...(await webTsxImplicitSubmitButtonViolations(path)))
      continue
    }

    if (!entry.isFile() || !path.endsWith('.tsx')) {
      continue
    }

    const source = await readFile(path, 'utf8').catch(() => '')

    for (const match of source.matchAll(/<button\b[\s\S]*?>/gu)) {
      if (/\btype\s*=/u.test(match[0])) {
        continue
      }

      const line = source.slice(0, match.index).split(/\r?\n/u).length
      const tag = match[0].replace(/\s+/gu, ' ').slice(0, 140)
      violations.push(`${path}:${line} ${tag}`)
    }
  }

  return violations
}

async function webTsxNativeTitleViolations(directory = 'src') {
  const entries = await readdir(directory, { withFileTypes: true }).catch(() => [])
  const violations = []

  for (const entry of entries) {
    const path = `${directory}/${entry.name}`

    if (entry.isDirectory()) {
      violations.push(...(await webTsxNativeTitleViolations(path)))
      continue
    }

    if (!entry.isFile() || !path.endsWith('.tsx')) {
      continue
    }

    const source = await readFile(path, 'utf8').catch(() => '')

    for (const match of source.matchAll(/<[A-Za-z][\s\S]*?>/gu)) {
      const tagName = match[0].match(/^<([A-Za-z][\w.]*)/u)?.[1] ?? ''

      if (!/^[a-z]/u.test(tagName) || !/\btitle\s*=/u.test(match[0])) {
        continue
      }

      const line = source.slice(0, match.index).split(/\r?\n/u).length
      const tag = match[0].replace(/\s+/gu, ' ').slice(0, 180)
      violations.push(`${path}:${line} ${tag}`)
    }
  }

  return violations
}

function formatAsiaShanghaiMinute(value) {
  const date = new Date(value)

  if (Number.isNaN(date.getTime())) {
    return ''
  }

  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-CA', {
      timeZone: 'Asia/Shanghai',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    })
      .formatToParts(date)
      .map((part) => [part.type, part.value]),
  )

  return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute} Asia/Shanghai`
}

function currentRequirementsHandoffNoteTimes(source) {
  const currentSection =
    source.match(
      /<!-- zerochat-current-evidence:requirements:start -->([\s\S]*?)<!-- zerochat-current-evidence:requirements:end -->/u,
    )?.[1] ?? ''

  return [
    ...currentSection.matchAll(
      /活跃 release blocker 交接以 ([^。]+?) 的机器可读 handoff/gu,
    ),
  ].map((match) => match[1])
}

function extractSupportedLocales(source) {
  const match = source.match(/const supportedLocales:\s*Locale\[\]\s*=\s*\[([\s\S]*?)\]/)

  if (!match) {
    failures.push('Unable to find supportedLocales in src/i18n.ts.')
    return []
  }

  const locales = [...match[1].matchAll(/'([^']+)'/g)].map((item) => item[1])

  if (locales.length === 0) {
    failures.push('src/i18n.ts supportedLocales is empty.')
  }

  return locales
}

function expectedVisualAuditScreenshotCount(visualAuditSource, i18nSource) {
  const match = visualAuditSource.match(/const visualAuditBaseScreenshotCount\s*=\s*(\d+)/)

  if (!match) {
    failures.push('Unable to derive visualAuditBaseScreenshotCount from scripts/visual-audit.mjs.')
    return 0
  }

  return Number(match[1]) + extractSupportedLocales(i18nSource).length
}

