async function fileExists(path) {
  try {
    await stat(path)
    return true
  } catch {
    return false
  }
}

function pngDimensions(buffer) {
  const pngSignature = '89504e470d0a1a0a'

  if (
    buffer.length < 24 ||
    buffer.subarray(0, 8).toString('hex') !== pngSignature ||
    buffer.subarray(12, 16).toString('ascii') !== 'IHDR'
  ) {
    return null
  }

  return {
    width: buffer.readUInt32BE(16),
    height: buffer.readUInt32BE(20),
  }
}

async function assertPngSize(path, width, height) {
  try {
    const size = pngDimensions(await readFile(path))

    if (!size) {
      failures.push(`${path} must be a valid PNG icon asset.`)
      return
    }

    if (size.width !== width || size.height !== height) {
      failures.push(
        `${path} must be ${width}x${height}px, got ${size.width}x${size.height}px.`,
      )
    }
  } catch (error) {
    failures.push(`Unable to inspect PNG icon ${path}: ${error.message}`)
  }
}

async function assertIcoSizes(path, expectedSizes) {
  try {
    const buffer = await readFile(path)

    if (
      buffer.length < 6 ||
      buffer.readUInt16LE(0) !== 0 ||
      buffer.readUInt16LE(2) !== 1
    ) {
      failures.push(`${path} must be a valid Windows ICO file.`)
      return
    }

    const count = buffer.readUInt16LE(4)
    const sizes = new Set()

    for (let index = 0; index < count; index += 1) {
      const offset = 6 + index * 16

      if (buffer.length < offset + 16) {
        failures.push(`${path} has a truncated ICO directory entry.`)
        return
      }

      const width = buffer[offset] || 256
      const height = buffer[offset + 1] || 256
      const bitDepth = buffer.readUInt16LE(offset + 6)
      sizes.add(`${width}x${height}`)

      if (bitDepth < 32) {
        failures.push(`${path} ${width}x${height} entry must be 32-bit.`)
      }
    }

    for (const size of expectedSizes) {
      if (!sizes.has(size)) {
        failures.push(`${path} must include a ${size} icon entry.`)
      }
    }
  } catch (error) {
    failures.push(`Unable to inspect Windows ICO ${path}: ${error.message}`)
  }
}

function svgViewBox(source) {
  const match = source.match(/\bviewBox=["']\s*0\s+0\s+([0-9.]+)\s+([0-9.]+)\s*["']/)

  if (!match) {
    return null
  }

  return {
    width: Number(match[1]),
    height: Number(match[2]),
  }
}

function assertSvgViewBox(source, path, width, height) {
  const box = svgViewBox(source)

  if (!box) {
    failures.push(`${path} must declare a 0 0 ${width} ${height} viewBox.`)
    return
  }

  if (box.width !== width || box.height !== height) {
    failures.push(
      `${path} must use a ${width}x${height} viewBox, got ${box.width}x${box.height}.`,
    )
  }
}

function lineCount(source) {
  return source.trimEnd().split(/\r?\n/).length
}

function workflowJobBlock(workflowSource, jobId) {
  const lines = workflowSource.split(/\r?\n/u)
  const start = lines.findIndex((line) => line === `  ${jobId}:`)

  if (start < 0) {
    return ''
  }

  const block = [lines[start]]
  for (let index = start + 1; index < lines.length; index += 1) {
    const line = lines[index]
    if (/^  [A-Za-z0-9_-]+:\s*$/u.test(line)) {
      break
    }
    block.push(line)
  }

  return block.join('\n')
}

function trackedFiles() {
  try {
    const output = execFileSync('git', ['ls-files', '-z'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    })

    return output.split('\0').filter(Boolean)
  } catch (error) {
    failures.push(`Unable to list tracked files with git: ${error.message}`)
    return []
  }
}

function repositoryFilesForSecretScan() {
  try {
    const output = execFileSync(
      'git',
      ['ls-files', '-z', '--cached', '--others', '--exclude-standard'],
      {
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe'],
      },
    )

    return output.split('\0').filter(Boolean)
  } catch (error) {
    failures.push(`Unable to list repository files for secret scan: ${error.message}`)
    return []
  }
}

function normalizeForMatch(path) {
  return `/${path.replaceAll('\\', '/')}`
}

async function assertLiveProviderUiScreenshotBindingFixture() {
  const currentReportPath = '.manual-qa/live-provider-ui-smoke-current.json'
  const fixtureCurrentPath =
    '.manual-qa/live-provider-ui-smoke-current-screenshot-binding-fixture.json'
  const fixtureAttemptPath =
    '.manual-qa/live-provider-ui-smoke-attempt-current-screenshot-binding-fixture.json'
  const fixtureScreenshotPath =
    '.manual-qa/web-live-ui-provider-smoke-screenshot-binding-fixture.png'
  const currentReport = await readJsonFile(currentReportPath)

  if (!currentReport) {
    failures.push('Live provider UI screenshot binding fixture needs the current UI report.')
    return
  }

  try {
    await copyFile('public/icon-180.png', fixtureScreenshotPath)
    const screenshotBytes = await readFile(fixtureScreenshotPath)
    const fixtureReport = JSON.parse(JSON.stringify(currentReport))
    fixtureReport.screenshot = {
      path: fixtureScreenshotPath,
      bytes: screenshotBytes.byteLength,
      sha256: createHash('sha256').update(screenshotBytes).digest('hex').toUpperCase(),
    }
    const brokenReport = JSON.parse(JSON.stringify(fixtureReport))
    brokenReport.screenshot = {
      ...brokenReport.screenshot,
      bytes: brokenReport.screenshot.bytes + 1,
      sha256: '0'.repeat(64),
    }

    await writeFile(fixtureCurrentPath, `${JSON.stringify(brokenReport, null, 2)}\n`)
    await writeFile(fixtureAttemptPath, `${JSON.stringify(fixtureReport, null, 2)}\n`)

    try {
      execFileSync(
        process.execPath,
        [
          'scripts/release-blocker-report.mjs',
          '--check-live-provider-ui-report',
          `--live-provider-ui-report=${fixtureCurrentPath}`,
          `--live-provider-ui-attempt-report=${fixtureAttemptPath}`,
        ],
        {
          encoding: 'utf8',
          stdio: ['ignore', 'pipe', 'pipe'],
        },
      )
      failures.push('Live provider UI screenshot binding fixture must reject mismatched metadata.')
    } catch (error) {
      const output = `${error.stdout ?? ''}\n${error.stderr ?? ''}\n${error.message}`

      if (
        !output.includes('screenshot.sha256 must match the current screenshot artifact') ||
        !output.includes('screenshot.bytes must match the current screenshot artifact')
      ) {
        failures.push(
          'Live provider UI screenshot binding fixture must fail on both mismatched screenshot sha256 and bytes.',
        )
      }
    }
  } finally {
    await rm(fixtureCurrentPath, { force: true })
    await rm(fixtureAttemptPath, { force: true })
    await rm(fixtureScreenshotPath, { force: true })
  }
}

async function assertHostedNativeCiSourceFingerprintFixture() {
  const reportPath = '.manual-qa/hosted-native-ci-evidence.json'
  const fixturePath = '.manual-qa/hosted-native-ci-evidence-source-fingerprint-fixture.json'
  const report = await readJsonFile(reportPath)

  if (!report) {
    failures.push('Hosted native CI source-fingerprint fixture needs the current diagnostic report.')
    return
  }

  const fixture = JSON.parse(JSON.stringify(report))
  fixture.currentNativeSourceFingerprint = {
    ...(fixture.currentNativeSourceFingerprint ?? {}),
    sha256: '0'.repeat(64),
  }
  if (fixture.missingEvidenceSummary) {
    fixture.missingEvidenceSummary.expectedReport = fixturePath
  }

  try {
    await writeFile(fixturePath, `${JSON.stringify(fixture, null, 2)}\n`)

    try {
      execFileSync(
        process.execPath,
        ['scripts/hosted-native-ci-evidence-check.mjs', `--report=${fixturePath}`],
        {
          encoding: 'utf8',
          stdio: ['ignore', 'pipe', 'pipe'],
        },
      )
      failures.push('Hosted native CI source-fingerprint fixture must reject stale metadata.')
    } catch (error) {
      const output = `${error.stdout ?? ''}\n${error.stderr ?? ''}\n${error.message}`

      if (!output.includes('must match the current native sourceFingerprint')) {
        failures.push(
          'Hosted native CI source-fingerprint fixture must fail on mismatched native sourceFingerprint.',
        )
      }
    }
  } finally {
    await rm(fixturePath, { force: true })
  }
}

function fixtureDirname(filePath) {
  const index = filePath.lastIndexOf('/')
  return index === -1 ? '.' : filePath.slice(0, index)
}

function fixtureBinary(size, magicBytes) {
  const bytes = Buffer.alloc(size)
  Buffer.from(magicBytes).copy(bytes, 0)
  return bytes
}

function fixturePng(width, height, size) {
  const bytes = Buffer.alloc(size)
  Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]).copy(bytes, 0)
  bytes.writeUInt32BE(13, 8)
  bytes.write('IHDR', 12, 'ascii')
  bytes.writeUInt32BE(width, 16)
  bytes.writeUInt32BE(height, 20)
  return bytes
}

async function writeFixtureFile(filePath, bytes) {
  await mkdir(fixtureDirname(filePath), { recursive: true })
  await writeFile(filePath, bytes)
}

async function fixtureFileEvidence(filePath) {
  const bytes = await readFile(filePath)
  return {
    path: filePath,
    bytes: bytes.length,
    sha256: createHash('sha256').update(bytes).digest('hex').toUpperCase(),
  }
}

async function writeJsonFixtureFile(filePath, value) {
  await writeFixtureFile(filePath, Buffer.from(`${JSON.stringify(value, null, 2)}\n`, 'utf8'))
}

async function assertHostedNativeCiReleaseReportFixture() {
  const fixtureRoot = '.manual-qa/hosted-native-ci/__fixture-release-report'
  const fixtureReportPath = '.manual-qa/hosted-native-ci-evidence-release-fixture.json'
  const nativePrereq = await readJsonFile('.manual-qa/native-prereq-all-platforms.json')
  const sourceFingerprint = nativePrereq?.sourceFingerprint
  const headSha = execFileSync('git', ['rev-parse', 'HEAD'], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  }).trim().toUpperCase()
  const generatedAt = '2026-06-26T00:00:00.000Z'
  const runId = '123456789'
  const runAttempt = 1
  const repository = 'owner/repo'
  const artifactFiles = new Map()

  if (!sourceFingerprint) {
    failures.push('Hosted native CI release-report fixture needs the current native source fingerprint.')
    return
  }

  async function recordArtifactFile(artifactName, relativePath, bytes) {
    const filePath = `${fixtureRoot}/${artifactName}/${relativePath}`
    await writeFixtureFile(filePath, bytes)
    const files = artifactFiles.get(artifactName) ?? []
    files.push(await fixtureFileEvidence(filePath))
    artifactFiles.set(artifactName, files)
    return filePath
  }

  async function writeNativePrereq(artifactName, platform) {
    return recordArtifactFile(
      artifactName,
      `native-prereq-${platform}.json`,
      Buffer.from(
        `${JSON.stringify(
          {
            kind: 'zerochat.nativeBuildPrereqReport',
            version: 1,
            evidenceType: 'toolchain-preflight-pass',
            passed: true,
            releaseEvidence: false,
            runtimeQaRequired: true,
            safeToPublish: true,
            selectedPlatform: platform,
            missing: [],
            sourceFingerprint,
          },
          null,
          2,
        )}\n`,
        'utf8',
      ),
    )
  }

  async function writeRuntimeSmoke(artifactName, platform, screenshotName, metadataName, extra = {}) {
    const screenshotBytes = platform === 'linux' ? 12_000 : 22_000
    const screenshotPath = await recordArtifactFile(
      artifactName,
      screenshotName,
      fixturePng(800, 450, screenshotBytes),
    )
    const screenshotEvidence = await fixtureFileEvidence(screenshotPath)
    await recordArtifactFile(
      artifactName,
      metadataName,
      Buffer.from(
        `${JSON.stringify(
          {
            platform,
            generatedAt,
            captureTarget: 'app-window',
            screenshot: screenshotName,
            bytes: screenshotEvidence.bytes,
            windowWidth: 800,
            windowHeight: 450,
            screenshotWidth: 800,
            screenshotHeight: 450,
            distinctColors: platform === 'apple' ? 16 : 32,
            ...extra,
          },
          null,
          2,
        )}\n`,
        'utf8',
      ),
    )
  }

  try {
    await rm(fixtureRoot, { recursive: true, force: true })
    await rm(fixtureReportPath, { force: true })

    await writeNativePrereq('windows-release-shell', 'windows')
    await writeRuntimeSmoke('windows-release-shell', 'windows', 'windows-webview-runtime-smoke.png', 'windows-webview-runtime-smoke.json', {
      webAssetsMatchDist: true,
      windowIcon: {
        titleBarIconPresent: true,
        executableIconPresent: true,
      },
      trayProbe: {
        passed: true,
      },
    })
    await recordArtifactFile(
      'windows-release-shell',
      'ZeroChat_0.0.1.0_x64.msix',
      fixtureBinary(120_000, [0x50, 0x4b, 0x03, 0x04]),
    )

    await writeNativePrereq('android-native-prereq', 'android')
    await recordArtifactFile(
      'android-debug-apk',
      'app-debug.apk',
      fixtureBinary(520_000, [0x50, 0x4b, 0x03, 0x04]),
    )
    const releaseApkPath = await recordArtifactFile(
      'android-release-apk',
      'app-release.apk',
      fixtureBinary(530_000, [0x50, 0x4b, 0x03, 0x04]),
    )
    const releaseApkEvidence = await fixtureFileEvidence(releaseApkPath)
    await recordArtifactFile(
      'android-release-apk',
      'android-release-size.json',
      Buffer.from(
        `${JSON.stringify(
          {
            schema: 'zerochat.androidReleaseSize.v1',
            passed: true,
            platform: 'android-release-apk',
            generatedAt,
            budget: {
              maxBytes: 8 * 1024 * 1024,
              label: 'PRD Android release APK < 8MB',
            },
            apk: releaseApkEvidence,
            zip: {
              entryCount: 3,
              hasAndroidManifest: true,
              hasClassesDex: true,
              hasResourcesArsc: true,
            },
            releaseOptimizations: {
              r8MinifyEnabled: true,
              resourceShrinkingEnabled: true,
              optimizedDefaultProguard: true,
              localProguardRules: true,
              suppressesTinkAnnotations: true,
              suppressesJavaxGuardedBy: true,
            },
          },
          null,
          2,
        )}\n`,
        'utf8',
      ),
    )

    await writeNativePrereq('linux-release-binary-and-runtime-smoke', 'linux')
    const linuxBinaryPath = await recordArtifactFile(
      'linux-release-binary-and-runtime-smoke',
      'zerochat-linux',
      fixtureBinary(140_000, [0x7f, 0x45, 0x4c, 0x46]),
    )
    const linuxBinaryEvidence = await fixtureFileEvidence(linuxBinaryPath)
    await writeRuntimeSmoke(
      'linux-release-binary-and-runtime-smoke',
      'linux',
      'linux-runtime-smoke.png',
      'linux-runtime-smoke.json',
      {
        binary: 'zerochat-linux',
        binaryEvidence: linuxBinaryEvidence,
      },
    )

    await writeNativePrereq('apple-runtime-smoke', 'apple')
    const appleRuntimeExecutablePath = await recordArtifactFile(
      'apple-runtime-smoke',
      'ZeroChat',
      fixtureBinary(24_000, [0xfe, 0xed, 0xfa, 0xcf]),
    )
    const appleRuntimeExecutableEvidence = await fixtureFileEvidence(appleRuntimeExecutablePath)
    await writeRuntimeSmoke(
      'apple-runtime-smoke',
      'apple',
      'apple-runtime-smoke.png',
      'apple-runtime-smoke.json',
      {
        bundleId: 'app.zerochat.client',
        executable: 'ZeroChat',
        executableEvidence: appleRuntimeExecutableEvidence,
        processAttribution: appleRuntimeProcessAttribution,
        cleanupPolicy: appleRuntimeCleanupPolicy,
        windowDiscovery: appleRuntimeWindowDiscovery,
      },
    )

    await recordArtifactFile(
      'apple-ios-simulator-build',
      'ZeroChat.app/Info.plist',
      Buffer.from(
        `<?xml version="1.0" encoding="UTF-8"?>\n<plist><dict><key>CFBundleIdentifier</key><string>app.zerochat.client</string><key>CFBundleExecutable</key><string>ZeroChat</string></dict></plist>\n`,
        'utf8',
      ),
    )
    await recordArtifactFile(
      'apple-ios-simulator-build',
      'ZeroChat.app/ZeroChat',
      fixtureBinary(24_000, [0xfe, 0xed, 0xfa, 0xcf]),
    )

    const expectedJobs = [
      ['windows-native', 'Windows native shell', 'windows-latest'],
      ['android-native', 'Android debug/release build', 'ubuntu-latest'],
      ['linux-native', 'Linux GTK release build', 'ubuntu-latest'],
      ['apple-core', 'Apple Swift/Xcode build', 'macos-latest'],
    ]
    const artifactJobs = new Map([
      ['windows-release-shell', 'windows-native'],
      ['android-native-prereq', 'android-native'],
      ['android-debug-apk', 'android-native'],
      ['android-release-apk', 'android-native'],
      ['linux-release-binary-and-runtime-smoke', 'linux-native'],
      ['apple-runtime-smoke', 'apple-core'],
      ['apple-ios-simulator-build', 'apple-core'],
    ])
    const report = {
      kind: 'zerochat.hostedNativeCiEvidence',
      version: 1,
      generatedAt,
      workflowFile: '.github/workflows/ci.yml',
      workflowName: 'CI',
      repository,
      runUrl: `https://github.com/${repository}/actions/runs/${runId}`,
      runId,
      runAttempt,
      headSha,
      releaseEvidence: true,
      safeToPublish: true,
      jobs: expectedJobs.map(([id, displayName, runner]) => ({
        id,
        name: id,
        displayName,
        runner,
        conclusion: 'success',
        runId,
        runAttempt,
      })),
      artifacts: [...artifactJobs].map(([name, job]) => ({
        name,
        job,
        runId,
        runAttempt,
        files: artifactFiles.get(name) ?? [],
      })),
    }

    await writeJsonFixtureFile(fixtureReportPath, report)
    execFileSync(
      process.execPath,
      ['scripts/hosted-native-ci-evidence-check.mjs', `--report=${fixtureReportPath}`, '--require'],
      {
        encoding: 'utf8',
        env: {
          ...process.env,
          ZEROCHAT_HOSTED_NATIVE_CI_RELEASE_FIXTURE: '1',
        },
        stdio: ['ignore', 'pipe', 'pipe'],
      },
    )
  } catch (error) {
    const output = `${error.stdout ?? ''}\n${error.stderr ?? ''}\n${error.message}`
    failures.push(`Hosted native CI release-report fixture must pass the release evidence checker: ${output}`)
  } finally {
    await rm(fixtureRoot, { recursive: true, force: true })
    await rm(fixtureReportPath, { force: true })
  }
}

