try {
  const manifest = JSON.parse(webManifest)
  const iconBySource = new Map(
    (manifest.icons ?? []).map((icon) => [icon.src, icon]),
  )

  if (
    manifest.background_color?.toLowerCase() !== '#fafbfc' ||
    manifest.theme_color?.toLowerCase() !== '#6366f1'
  ) {
    failures.push(
      'PWA manifest must use the PRD Web brand colors: background #fafbfc and theme #6366f1.',
    )
  }

  for (const [source, sizes] of [
    ['favicon.svg', 'any'],
    ['icon-192.png', '192x192'],
    ['icon-512.png', '512x512'],
  ]) {
    const icon = iconBySource.get(source)

    if (!icon) {
      failures.push(`PWA manifest must declare ${source}.`)
      continue
    }

    if (icon.sizes !== sizes) {
      failures.push(`PWA manifest ${source} must declare sizes=${sizes}.`)
    }

    if (!String(icon.purpose ?? '').includes('maskable')) {
      failures.push(`PWA manifest ${source} must be maskable for install surfaces.`)
    }
  }
} catch (error) {
  failures.push(`public/manifest.webmanifest must parse as JSON: ${error.message}`)
}

