for (const file of trackedFiles()) {
  const normalized = normalizeForMatch(file)

  for (const fragment of forbiddenTrackedFragments) {
    if (normalized.includes(fragment)) {
      failures.push(`Build/local artifact should not be tracked: ${file}`)
      break
    }
  }
}

for (const file of repositoryFilesForSecretScan()) {
  const normalized = normalizeForMatch(file)

  if (forbiddenTrackedFragments.some((fragment) => normalized.includes(fragment))) {
    continue
  }

  if (
    secretAllowlist.includes(file) ||
    /\.(?:png|jpg|jpeg|webp|gif|ico|pdf|lock|jar|zip)$/i.test(file)
  ) {
    continue
  }

  const text = await readFile(file, 'utf8').catch(() => '')

  for (const pattern of secretPatterns) {
    pattern.lastIndex = 0

    if (pattern.test(text)) {
      failures.push(`Possible secret found in tracked source: ${file}`)
      break
    }
  }
}

